@tool
def search_along_route(query=''):
    points = global_context['route_points']
    _archive_previous_results()
    results = search_along_route_w_coordinates(points, query)
    global_context['last_route_results'] = {'query': query, 'results': results}
    return results


def _archive_previous_results():
    # Move the previous search results out of the active slot into history
    previous = global_context.pop('last_route_results', None)
    if previous is not None:
        history = global_context.setdefault('route_results_history', [])
        history.append(previous)
